# ============================================================================
# new-cuda-project.ps1   (single-file edition)
# ----------------------------------------------------------------------------
# One-shot bootstrap for a CUDA C++ project on a Sussex lab Windows machine.
#
# Student workflow:
#     .\new-cuda-project.ps1 -Name my-first-kernel
#
# What it does, in order:
#   1. Validates the project name.
#   2. Checks WSL is enabled on this machine (fails fast with IT message if not).
#   3. Ensures the "LabGPU" WSL distro exists; provisions it if absent.
#   4. Ensures the CUDA toolkit is installed inside LabGPU; installs if absent.
#   5. Creates the project folder + writes all template files inside WSL.
#   6. Opens the project in VS Code via WSL-remote.
#
# This single-file version embeds all bash scripts and template files as
# here-strings. They are extracted to a temporary directory at run time,
# pushed into WSL with correct (LF) line endings, and executed.
#
# Re-running with the same name is safe: the script is idempotent up to
# step 5, where it refuses to overwrite an existing project unless -Force.
#
# Why WSL? CUDA C++ on Windows needs MSVC as the host compiler, and MSVC
# needs Visual Studio (admin). WSL sidesteps that — apt installs the toolkit
# user-mode and g++ is the host compiler. The only one-time admin step is
# enabling WSL itself (IT runs `wsl --install --no-distribution` once per
# machine); after that, students provision distros + install CUDA bits
# entirely user-mode.
#
# Prerequisites (one-time, done by IT, with admin rights):
#   - WSL enabled:   wsl --install --no-distribution    (then reboot)
#   - NVIDIA Windows driver with WSL passthrough (any post-2021 driver)
#   - VS Code installed (user-mode installer is fine, no admin needed)
#
# ----------------------------------------------------------------------------
# THIS FILE IS GENERATED BY build.ps1 FROM script-template.ps1 + template/.
# Do not edit the distributed script directly — edit the sources and rebuild.
# ============================================================================

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string]$Name,

    [Parameter()]
    [ValidateSet('cuda')]
    [string]$Type = 'cuda',

    [Parameter()]
    [switch]$Force
)

$ErrorActionPreference = 'Stop'

# ============================================================================
# CONFIGURATION
# ============================================================================

$DistroName        = 'LabGPU'
$DistroInstallDir  = Join-Path $env:LOCALAPPDATA "WSL\$DistroName"
$DistroTarballURL  = 'https://cloud-images.ubuntu.com/wsl/jammy/current/ubuntu-jammy-wsl-amd64-ubuntu22.04lts.rootfs.tar.gz'
$CudaToolkitVer    = '12.8'   # major.minor — apt package name is cuda-toolkit-12-8
$ProjectsRoot      = 'projects'

# ============================================================================
# EMBEDDED FILES
# ----------------------------------------------------------------------------
# Each $E_* is the literal content of a file we'll write out at run time.
# Single-quoted here-strings (@'...'@) preserve everything literally — no
# variable interpolation, no escaping of $ or `. Placeholders like
# __PROJECT_NAME__ are substituted on the Linux side by sed.
#
# The here-strings below are populated at build time by build.ps1 from the
# files in linux/ and template/. The {{TEMPLATE: ...}} markers are the
# build's hook.
# ============================================================================

$E_bootstrap_distro = @'
#!/usr/bin/env bash
# First-run distro setup: creates a normal user, sets as default, installs
# baseline packages. Runs as root immediately after `wsl --import`.
set -euo pipefail

WIN_USER="${1:-student}"
LINUX_USER=$(echo "$WIN_USER" | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9_-')
if [[ -z "$LINUX_USER" || ! "$LINUX_USER" =~ ^[a-z] ]]; then
    LINUX_USER="student"
fi

echo "[bootstrap-distro] Creating Linux user '$LINUX_USER'..."
if ! id -u "$LINUX_USER" >/dev/null 2>&1; then
    useradd --create-home --shell /bin/bash "$LINUX_USER"
    usermod -aG sudo "$LINUX_USER"
    echo "$LINUX_USER ALL=(ALL) NOPASSWD:ALL" > "/etc/sudoers.d/90-$LINUX_USER"
    chmod 0440 "/etc/sudoers.d/90-$LINUX_USER"
fi

cat > /etc/wsl.conf <<EOF
[user]
default=$LINUX_USER

[boot]
systemd=false

[interop]
appendWindowsPath=true
EOF

echo "[bootstrap-distro] Installing baseline apt packages..."
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq --no-install-recommends \
    sudo build-essential ca-certificates curl wget git gnupg \
    cmake ninja-build pkg-config unzip xz-utils bzip2
apt-get clean
rm -rf /var/lib/apt/lists/*

echo "[bootstrap-distro] Done."
'@

$E_ensure_cuda = @'
#!/usr/bin/env bash
# Installs the CUDA toolkit system-wide via NVIDIA's official WSL apt repo.
# No conda, no Miniconda — just the CUDA bits NVIDIA ships for WSL Ubuntu.
#
# This is what NVIDIA recommends for WSL:
#   https://docs.nvidia.com/cuda/wsl-user-guide/
#
# The wsl-ubuntu repo deliberately omits the GPU kernel driver (the Windows
# host driver passes through), so we only get the toolkit bits.
#
# Usage: ensure-cuda.sh <cuda_version>   e.g. ensure-cuda.sh 12.8
set -euo pipefail

CUDA_VER="${1:?missing CUDA version}"            # e.g. 12.8
CUDA_PKG_SUFFIX="${CUDA_VER//./-}"               # 12.8 -> 12-8
PKG="cuda-toolkit-${CUDA_PKG_SUFFIX}"
KEYRING_URL="https://developer.download.nvidia.com/compute/cuda/repos/wsl-ubuntu/x86_64/cuda-keyring_1.1-1_all.deb"

echo "[ensure-cuda] Target package: $PKG"

if dpkg -s "$PKG" >/dev/null 2>&1; then
    installed=$(dpkg-query -W -f='${Version}' "$PKG" 2>/dev/null || echo "unknown")
    echo "[ensure-cuda] $PKG already installed (version $installed). Nothing to do."
else
    echo "[ensure-cuda] Installing NVIDIA CUDA repo keyring..."
    tmp_deb=$(mktemp --suffix=.deb)
    trap 'rm -f "$tmp_deb"' EXIT
    curl -fsSL "$KEYRING_URL" -o "$tmp_deb"
    sudo dpkg -i "$tmp_deb" >/dev/null

    echo "[ensure-cuda] apt-get update (NVIDIA repo)..."
    sudo apt-get update -qq

    echo "[ensure-cuda] Installing $PKG (this is the big download)..."
    sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends "$PKG"
fi

# Wire up PATH and LD_LIBRARY_PATH idempotently. NVIDIA installs to
# /usr/local/cuda-X.Y with a /usr/local/cuda symlink to the active one,
# but the wsl-ubuntu apt package doesn't add anything to PATH for you.
# We need three flavours of fix to cover all the shell contexts a student
# might hit:
#   - /etc/profile.d/cuda.sh    -> login shells (ssh, wsl bash -l)
#   - ~/.bashrc append          -> interactive non-login (VS Code terminals)
#   - /usr/local/bin symlinks   -> non-interactive (`bash -c`, scripts,
#                                  cmake invoked from outside an env)
sudo tee /etc/profile.d/cuda.sh >/dev/null <<'EOF'
export PATH="/usr/local/cuda/bin:$PATH"
export LD_LIBRARY_PATH="/usr/local/cuda/lib64:${LD_LIBRARY_PATH:-}"
EOF
sudo chmod 0644 /etc/profile.d/cuda.sh

PROFILE_LINE_MARKER='# Added by lab-gpu ensure-cuda.sh'
if ! grep -qF "$PROFILE_LINE_MARKER" "$HOME/.bashrc" 2>/dev/null; then
    {
        echo ''
        echo "$PROFILE_LINE_MARKER"
        echo 'export PATH="/usr/local/cuda/bin:$PATH"'
        echo 'export LD_LIBRARY_PATH="/usr/local/cuda/lib64:${LD_LIBRARY_PATH:-}"'
    } >> "$HOME/.bashrc"
fi

for bin in nvcc cuda-gdb; do
    sudo ln -sf "/usr/local/cuda/bin/$bin" "/usr/local/bin/$bin"
done

# Activate for this script's verification step.
export PATH="/usr/local/cuda/bin:$PATH"
export LD_LIBRARY_PATH="/usr/local/cuda/lib64:${LD_LIBRARY_PATH:-}"

echo ""
echo "[ensure-cuda] Verifying:"
echo -n "  nvcc:   "; nvcc --version 2>/dev/null | grep -oE 'release [0-9]+\.[0-9]+' || echo "MISSING"
echo -n "  cmake:  "; cmake --version 2>/dev/null | head -n1 || echo "MISSING"
echo -n "  ninja:  "; ninja --version 2>/dev/null || echo "MISSING"
# Deliberately not calling nvidia-smi here. On WSL, all GPU traffic routes
# through /dev/dxg to the Windows host driver. If that driver's userspace
# state is stale (a long-lived distro session, a driver update mid-session,
# etc.), nvidia-smi enters uninterruptible kernel sleep (D state) that even
# SIGKILL can't break — and `timeout` is useless against D state.
#
# The cure for that condition is `wsl --shutdown` on the Windows side, which
# costs the student nothing. So we just tell them how to check, rather than
# risk hanging the installer.
echo "  driver: run 'nvidia-smi' in a new WSL terminal to check. If it hangs,"
echo "          run 'wsl --shutdown' in PowerShell on Windows and try again."
echo ""
echo "[ensure-cuda] Done."
'@

$E_make_project = @'
#!/usr/bin/env bash
# Creates a new project folder inside WSL and instantiates template files.
#
# Usage: make-project.sh <name> <type> <projects_root> [--force]
set -euo pipefail

NAME="${1:?missing project name}"
TYPE="${2:?missing project type}"
PROJECTS_ROOT="${3:?missing projects root}"
FORCE=""
if [[ "${4:-}" == "--force" ]]; then FORCE="1"; fi

CUDA_ARCH="86"
TEMPLATE_ROOT="$HOME/.lab-gpu/templates/$TYPE"
PROJECT_DIR="$HOME/$PROJECTS_ROOT/$NAME"

if [[ ! -d "$TEMPLATE_ROOT" ]]; then
    echo "[make-project] ERROR: no template for type '$TYPE' at $TEMPLATE_ROOT" >&2
    exit 1
fi

if [[ -e "$PROJECT_DIR" ]]; then
    if [[ -z "$FORCE" ]]; then
        echo "[make-project] ERROR: '$PROJECT_DIR' already exists. Use -Force to overwrite." >&2
        exit 2
    fi
    echo "[make-project] Removing existing $PROJECT_DIR (--force)"
    rm -rf "$PROJECT_DIR"
fi

mkdir -p "$PROJECT_DIR"
cp -a "$TEMPLATE_ROOT/." "$PROJECT_DIR/"

find "$PROJECT_DIR" -type f \( \
        -name '*.txt'  -o -name '*.md'   -o -name '*.cu' -o \
        -name '*.cpp'  -o -name '*.h'    -o -name '*.hpp' -o \
        -name '*.json' -o -name '*.yml'  -o -name '*.yaml' -o \
        -name '*.cmake' -o -name 'CMakeLists.txt' -o -name '.gitignore' \
     \) -print0 |
while IFS= read -r -d '' f; do
    sed -i \
        -e "s|__PROJECT_NAME__|$NAME|g" \
        -e "s|__CUDA_ARCH__|$CUDA_ARCH|g" \
        -e "s|__USER__|$USER|g" \
        "$f"
done

if command -v git >/dev/null 2>&1; then
    (
        cd "$PROJECT_DIR"
        git init -q -b main
        git add .
        git -c user.email="lab@local" -c user.name="lab-gpu" \
            commit -q -m "Initial project from lab-gpu template ($TYPE)"
    )
fi

echo "[make-project] Created $PROJECT_DIR"
'@

$E_cmakelists = @'
# CMakeLists.txt for __PROJECT_NAME__
cmake_minimum_required(VERSION 3.18)

# If nvcc isn't on PATH (raw `cmake ..` from a non-interactive shell where
# bashrc didn't run), fall back to the canonical apt-install location. VS
# Code passes this explicitly via settings.json; this is the belt to that
# braces for terminals/scripts/CI.
if(NOT DEFINED CMAKE_CUDA_COMPILER AND EXISTS "/usr/local/cuda/bin/nvcc")
    set(CMAKE_CUDA_COMPILER "/usr/local/cuda/bin/nvcc")
endif()

project(__PROJECT_NAME__ LANGUAGES CXX CUDA)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)
set(CMAKE_CUDA_STANDARD 17)
set(CMAKE_CUDA_STANDARD_REQUIRED ON)

# Lab GPUs are NVIDIA A4000 = Ampere SM 8.6. If you copy this project
# elsewhere, change the architecture below.
set(CMAKE_CUDA_ARCHITECTURES __CUDA_ARCH__)

if(NOT CMAKE_BUILD_TYPE AND NOT CMAKE_CONFIGURATION_TYPES)
    set(CMAKE_BUILD_TYPE Release CACHE STRING "" FORCE)
endif()

set(CMAKE_EXPORT_COMPILE_COMMANDS ON)

add_executable(__PROJECT_NAME__ main.cu)

find_package(CUDAToolkit REQUIRED)
target_link_libraries(__PROJECT_NAME__ PRIVATE
    CUDA::cudart
    # CUDA::cublas
    # CUDA::curand
    # CUDA::cufft
)

message(STATUS "Project:    __PROJECT_NAME__")
message(STATUS "CUDA arch:  ${CMAKE_CUDA_ARCHITECTURES}")
message(STATUS "Build type: ${CMAKE_BUILD_TYPE}")
message(STATUS "nvcc:       ${CMAKE_CUDA_COMPILER}")
'@

$E_main_cu = @'
// main.cu - __PROJECT_NAME__
// Minimal but real CUDA: vector addition on the GPU.
// If this builds and runs, your whole toolchain is working.

#include <cstdio>
#include <cstdlib>
#include <vector>
#include <cuda_runtime.h>

#define CUDA_CHECK(expr)                                                    \
    do {                                                                    \
        cudaError_t err__ = (expr);                                         \
        if (err__ != cudaSuccess) {                                         \
            std::fprintf(stderr, "CUDA error at %s:%d: %s\n",               \
                         __FILE__, __LINE__, cudaGetErrorString(err__));    \
            std::exit(EXIT_FAILURE);                                        \
        }                                                                   \
    } while (0)

__global__ void vector_add(const float* a, const float* b, float* c, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) c[i] = a[i] + b[i];
}

int main() {
    int device = 0;
    CUDA_CHECK(cudaGetDevice(&device));
    cudaDeviceProp props{};
    CUDA_CHECK(cudaGetDeviceProperties(&props, device));
    std::printf("Device:       %s\n", props.name);
    std::printf("Compute cap:  %d.%d\n", props.major, props.minor);
    std::printf("SMs:          %d\n", props.multiProcessorCount);
    std::printf("Global mem:   %.1f GB\n",
                static_cast<double>(props.totalGlobalMem) / (1024.0 * 1024.0 * 1024.0));

    constexpr int N = 1 << 20;
    constexpr int BYTES = N * sizeof(float);

    std::vector<float> h_a(N), h_b(N), h_c(N, 0.0f);
    for (int i = 0; i < N; ++i) {
        h_a[i] = static_cast<float>(i);
        h_b[i] = static_cast<float>(2 * i);
    }

    float *d_a = nullptr, *d_b = nullptr, *d_c = nullptr;
    CUDA_CHECK(cudaMalloc(&d_a, BYTES));
    CUDA_CHECK(cudaMalloc(&d_b, BYTES));
    CUDA_CHECK(cudaMalloc(&d_c, BYTES));

    CUDA_CHECK(cudaMemcpy(d_a, h_a.data(), BYTES, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(d_b, h_b.data(), BYTES, cudaMemcpyHostToDevice));

    constexpr int THREADS_PER_BLOCK = 256;
    const int blocks = (N + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK;
    vector_add<<<blocks, THREADS_PER_BLOCK>>>(d_a, d_b, d_c, N);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());

    CUDA_CHECK(cudaMemcpy(h_c.data(), d_c, BYTES, cudaMemcpyDeviceToHost));

    int errors = 0;
    for (int i = 0; i < N; ++i) {
        const float expected = static_cast<float>(i) + static_cast<float>(2 * i);
        if (h_c[i] != expected) {
            if (errors < 5)
                std::fprintf(stderr, "  mismatch at %d: got %f, expected %f\n",
                             i, h_c[i], expected);
            ++errors;
        }
    }

    CUDA_CHECK(cudaFree(d_a));
    CUDA_CHECK(cudaFree(d_b));
    CUDA_CHECK(cudaFree(d_c));

    if (errors == 0) {
        std::printf("OK: %d elements, all correct.\n", N);
        return 0;
    } else {
        std::printf("FAIL: %d / %d elements were wrong.\n", errors, N);
        return 1;
    }
}
'@

